arguments.command:
python -c "
import pynwb, h5py, numpy as np
f = h5py.File('/app/data/sub-m11/sub-m11_ses-03_behavior+ophys.nwb','r')
def show(name, obj):
    if isinstance(obj, h5py.Dataset):
        print(name, obj.shape, obj.dtype)
